update pages set contenu = '{"gabarit":"casclients","chapeau":"Pas de logos alignés sans contexte. Chaque référence ci-dessous indique l’offre engagée, la durée réelle et ce qui a été remis en marche.","chiffres":{"principal":{"valeur":"+10 M€","libelle":"de chiffre d’affaires, en croissance de +40 % année sur année. Une structure qui tient l’échelle nationale."},"cartes":[],"duo":[]},"chantiers":[],"avis":{"note":"4,6","mention":"sur 37 avis Google vérifiés","verbatims":[]}}'::jsonb where path = '/realisations/';
update pages set contenu = jsonb_set(contenu, '{chiffres,cartes}', (contenu #> '{chiffres,cartes}') || '[{"valeur":"4","libelle":"agences"},{"valeur":"+120","libelle":"techniciens"}]'::jsonb) where path = '/realisations/';
update pages set contenu = jsonb_set(contenu, '{chiffres,duo}', (contenu #> '{chiffres,duo}') || '[{"valeur":"+120","libelle":"techniciens"},{"valeur":"+200","libelle":"clients"}]'::jsonb) where path = '/realisations/';
update pages set contenu = jsonb_set(contenu, '{chantiers}', (contenu #> '{chantiers}') || '[{"client":"SUEZ IWT","duree":"11 semaines","titre":"Remise en état complète d’un site industriel","resume":"Reprise de tuyauterie, électricité et mécanique sur un site arrêté depuis huit mois. Redémarrage tenu à la date annoncée.","offre":"migen© Chantier","date":"Février 2026","image":"/assets/web/ph-tuyaux.jpg","href":"/preuves/suez-remise-en-etat/"},{"client":"DANONE","duree":"18 mois","titre":"Maintenance en continu des lignes de production","resume":"Trois techniciens en résidence, astreinte week-end, reprise complète des gammes de préventif sur douze équipements.","offre":"migen© Résidence","date":"Février 2026","image":"/assets/web/team-electric.jpg","href":"/preuves/danone-lignes-de-production/"},{"client":"JTEKT","duree":"6 mois","titre":"Sécuriser la maintenance de ses installations","resume":"Mise en conformité des consignations et formation des équipes internes aux procédures de sécurité machine.","offre":"migen© Résidence","date":"Janvier 2026","image":"/assets/web/x-auto-ligne.jpg","href":"/preuves/jtekt/"},{"client":"GLS","duree":"4 semaines","titre":"Maintenance curative de sa plateforme logistique","resume":"Convoyeurs et trieurs remis en disponibilité avant le pic saisonnier, en horaires décalés pour ne pas couper l’exploitation.","offre":"migen© Intervention","date":"Décembre 2025","image":"/assets/web/ph-hero-raffinerie.jpg","href":"/preuves/gls-maintenance-curative/"},{"client":"ALPINA SAVOIE","duree":"12 mois","titre":"Un soudeur-chaudronnier en poste longue durée","resume":"Reprise de structure et de trémies sur site agroalimentaire, avec contraintes de nettoyabilité.","offre":"migen© Résidence","date":"Novembre 2025","image":"/assets/web/team-grind-front.jpg"},{"client":"SANOFI MARCY","duree":"3 semaines","titre":"Mise en conformité d’une installation de dosage","resume":"Reprise des schémas, analyse de risques et dossier technique complet en environnement pharmaceutique.","offre":"migen© Bureau d’études","date":"Octobre 2025","image":"/assets/web/x-elec-disjoncteur.jpg"}]'::jsonb) where path = '/realisations/';
